//! An example calculator app that parses an integer arithmetic expression
//! and outputs a result, using pgen.zig for parsing.
const std = @import("std");
/// This parser is generated by pgen.zig during build process from
/// src/grammar.txt. See how the build integration works in build.zig.
const parser_mod = @import("parser");

pub fn main(init: std.process.Init) !u8 {
    const io = init.io;
    // This is appropriate for anything that lives as long as the process.
    const arena: std.mem.Allocator = init.arena.allocator();

    var arg_it = try init.minimal.args.iterateAllocator(arena);
    defer arg_it.deinit();
    std.debug.assert(arg_it.skip());
    const expression_src = arg_it.next() orelse {
        std.debug.print("expected one argument (the math expression to compute)\n", .{});
        return 1;
    };

    var stdout_buffer: [1024]u8 = undefined;
    var stdout_file_writer: std.Io.File.Writer = .init(.stdout(), io, &stdout_buffer);
    const stdout_writer = &stdout_file_writer.interface;

    var expression_reader: std.Io.Reader = .fixed(expression_src);
    var tokenizer: Tokenizer = .{
        .reader = &expression_reader,
        .payload_allocator = arena,
    };
    // Create the auto-generated parser instance. You can have multiple parsers
    // in your application.
    var parser = try parser_mod.Parser.init(arena);
    defer parser.deinit(arena);
    while (try tokenizer.nextToken()) |token| {
        errdefer token.deinit(arena);
        try parser.feed(arena, token);
        if (token.tag == .@"$") {
            // The EOI token does not end up in the CST and needs to be freed
            // separately since we specified -cst-owns-token.
            token.deinit(arena);
        }
    }
    // Obtain the parsed tree!
    var cst = parser.retrieve();
    defer cst.deinit(arena);

    // Now we can evaluate the expression.
    const evaluator: Evaluator = .{};
    const result = try evaluator.evalExpr(cst);
    try stdout_writer.print("The result is: {}\n", .{result});

    try stdout_writer.flush();
    return 0;
}

const OverflowError = error{
    /// Either at tokenization stage or at parsing/evaluation stage
    IntegerOverflow,
};

/// Integer type used during expression calculation.
/// This must be signed and consistent with the -token-extra definition
/// in build.zig.
const Int = i32;

/// pgen.zig handles *parsing* but not *tokenizing* or *lexing*, so you need to
/// supply your own tokenizer. Or, if your input is not a string then you may not
/// need a tokenizer.
const Tokenizer = struct {
    reader: *std.Io.Reader,
    payload_allocator: std.mem.Allocator,
    sent_eoi: bool = false,

    /// For this simple example we will not be providing detailed error messages
    pub const Error = error{ReadFailed} || std.mem.Allocator.Error || OverflowError || error{
        TokenizeFailed,
    };

    /// Get the next token. Newly created token must be deinited with
    /// `self.payload_allocator`.
    pub fn nextToken(self: *@This()) Error!?parser_mod.Token {
        while (true) {
            const first = self.reader.takeByte() catch |err| switch (err) {
                error.EndOfStream => return self.eoiToken(),
                error.ReadFailed => |e| return e,
            };
            if (std.ascii.isDigit(first)) {
                var num: Int = first - '0';
                while (true) {
                    const char = self.reader.peekByte() catch |err| switch (err) {
                        error.ReadFailed => |e| return e,
                        error.EndOfStream => break,
                    };
                    if (std.ascii.isDigit(char)) {
                        self.reader.toss(1);
                        const x, const overflow1 = @mulWithOverflow(num, 10);
                        if (overflow1 > 0)
                            return error.IntegerOverflow;
                        const y, const overflow2 = @addWithOverflow(x, char - '0');
                        if (overflow2 > 0)
                            return error.IntegerOverflow;
                        num = y;
                    } else {
                        break;
                    }
                }
                // Emit an INTEGER token with a payload!
                // The extra field is specified through pgenzig CLI (see build.zig).
                return .{ .tag = .INTEGER, .num = num };
            } else if (parser_mod.Token.literal_map.@".".get((&first)[0..1])) |tag| {
                // This is the benefit of pgen.zig's unique literal token system!
                // You can lookup a character/string directly from a comptime-generated
                // map. @"." means no literal suffix.
                return .{ .tag = tag, .num = undefined };
            } else {
                // For our simple grammar, anything else is an error
                return Error.TokenizeFailed;
            }
        }
    }

    fn eoiToken(self: *@This()) ?parser_mod.Token {
        defer self.sent_eoi = true;
        return if (self.sent_eoi) null else parser_mod.Token{
            .tag = .@"$",
            .num = undefined,
        };
    }
};

// pgen.zig handles parsing, but you'll need to consume the parse result
// yourself. In this app, the generated parse tree is consumed by this evaluator
// which computes the result for the expression.
const Evaluator = struct {
    pub const Error = OverflowError || error{
        DivisionByZero,
    };

    pub fn evalExpr(self: @This(), cst: parser_mod.CstNode) Error!Int {
        // expr: term (("+" | "-") term)*;
        // This obtain an iterator over the children, asserting node type is
        // "expr".
        var it = cst.internal.iteratorOf(.expr);
        // Eval the first expression.
        var value = try self.evalTerm(it.eat().*);
        while (it.next()) |operator_node| {
            const operator_token = operator_node.leaf;
            // Literal tokens are named in the form @"suffix.string" in Zig.
            // Since our literal tokens have empty suffix, they start with ".".
            const operand = try self.evalTerm(it.eat().*);
            value, const overflow = switch (operator_token.tag) {
                .@".+" => @addWithOverflow(value, operand),
                .@".-" => @subWithOverflow(value, operand),
                else => unreachable,
            };
            if (overflow > 0)
                return Error.IntegerOverflow;
        }
        return value;
    }

    pub fn evalTerm(self: @This(), cst: parser_mod.CstNode) Error!Int {
        // term: unary (("*" | "/") unary)*;
        var it = cst.internal.iteratorOf(.term);
        // Eval the first expression.
        var value = try self.evalUnary(it.eat().*);
        while (it.next()) |operator_node| {
            const operator_token = operator_node.leaf;
            const operand = try self.evalUnary(it.eat().*);
            switch (operator_token.tag) {
                .@".*" => {
                    value, const overflow = @mulWithOverflow(value, operand);
                    if (overflow > 0) {
                        return Error.IntegerOverflow;
                    }
                },
                .@"./" => {
                    if (operand == 0) {
                        return Error.DivisionByZero;
                    }
                    if (value == std.math.minInt(Int) and operand == -1) {
                        return Error.IntegerOverflow;
                    }
                    value = @divFloor(value, operand);
                },
                else => unreachable,
            }
        }
        return value;
    }

    pub fn evalUnary(self: @This(), cst: parser_mod.CstNode) Error!Int {
        // unary: ["-"] factor;
        if (cst.internal.children.len == 2) {
            // Has negative sign
            const n = try self.evalFactor(cst.internal.children[1]);
            if (n == std.math.minInt(Int)) {
                return Error.IntegerOverflow;
            }
            return -n;
        } else {
            return self.evalFactor(cst.internal.children[0]);
        }
    }

    pub fn evalFactor(self: @This(), cst: parser_mod.CstNode) Error!Int {
        // factor: INTEGER | "(" expr ")";
        if (cst.internal.children.len == 1) {
            // Accessing a custom field we defined in build.zig.
            return cst.internal.children[0].leaf.num;
        }
        std.debug.assert(cst.internal.children.len == 3);
        return self.evalExpr(cst.internal.children[1]);
    }
};
